from __future__ import annotations

from decimal import ROUND_HALF_UP, Decimal

#: 金额的量化步长 —— 与账本那一列一样。
MONEY_QUANTUM = Decimal("0.01")


class Money:
    """一笔钱 —— 金额与币种缺一不可。"""

    # ``__slots__`` 只挡住**新增**属性，挡不住对已有属性的赋值 —— 所以
    # 真正存值的是两个私有槽位（名字会被改写成 ``_Money__amount`` 一类，
    # 外部碰不到），对外的 ``amount`` / ``currency`` 是**只读属性**。
    # 要改一笔钱，只能造一笔新的。
    __slots__ = ("__amount", "__currency")

    def __init__(self, amount, currency):
        if not isinstance(amount, Decimal):
            amount = Decimal(str(amount))
        if not currency or not str(currency).strip():
            raise ValueError("币种不能是空白")
        self.__amount = amount.quantize(MONEY_QUANTUM, rounding=ROUND_HALF_UP)
        self.__currency = str(currency).strip().upper()

    @property
    def amount(self):
        """这笔钱的数额 —— **只读**，赋值会抛 ``AttributeError``。"""
        return self.__amount

    @property
    def currency(self):
        """这笔钱的币种 —— **只读**，赋值会抛 ``AttributeError``。"""
        return self.__currency

    def __repr__(self):
        return f"Money({self.amount}, {self.currency!r})"

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.amount == other.amount and self.currency == other.currency

    def __hash__(self):
        return hash((self.amount, self.currency))

    def add(self, other):
        """相加。**币种不一样就报错** —— 换个币种记一笔账比记错数字更坏。"""
        self._assert_same_currency(other)
        return Money(self.amount + other.amount, self.currency)

    def multiply(self, factor):
        """乘一个系数。"""
        return Money(self.amount * Decimal(str(factor)), self.currency)

    def is_zero(self):
        return self.amount == Decimal("0")

    def _assert_same_currency(self, other):
        if other.currency != self.currency:
            raise ValueError(
                f"币种不一样，不能相加：{self.currency} 与 {other.currency}"
            )


def total(amounts):
    """把若干笔钱加起来。"""
    if not amounts:
        raise ValueError("空列表没有合计")
    result = amounts[0]
    for amount in amounts[1:]:
        result = result.add(amount)
    return result


